//! `example.env`, generated from the schemas and the compose files: what
//! stays off git (secrets, private values, neutral overrides and compose's
//! own variables), every line commented out.

use crate::{
	compose::ComposeVariables,
	schema::{Class, Kind, Schema, Variable, SET},
	values::bound_text,
};
use std::{
	collections::{BTreeMap, BTreeSet},
	fmt::Write as _,
};

const BANNER: &str = "\
###############################################
#   GENERATED: do not edit this file by hand
###############################################
# `make env-schema` writes it from each binary's clap Config (checked in as
# infra/env/<binary>.json) and the compose files' ${...} variables, with the
# header in infra/env/example.env.head. CI fails when it differs. To change a
# variable's help or default, change it where it is declared and regenerate.
# `make env` lists every variable and which ones your .env sets; `make
# preflight` checks .env before `docker compose up`.";

const WIDTH: usize = 76;

fn quote(value: &str) -> String {
	format!("\"{}\"", value.replace('\\', r"\\").replace('"', "\\\""))
}

/// `line` wrapped as Python's `textwrap.wrap(line, 76, break_long_words=False,
/// break_on_hyphens=False)` wraps it: greedy over whitespace-separated
/// chunks, a word longer than the width on a line of its own, whitespace at
/// a break dropped.
fn wrap(line: &str) -> Vec<String> {
	let text: String = line.chars().map(|character| if character.is_whitespace() { ' ' } else { character }).collect();
	let mut chunks: Vec<String> = Vec::new();
	for character in text.chars() {
		let space = character == ' ';
		match chunks.last_mut() {
			Some(last) if last.starts_with(' ') == space => last.push(character),
			_ => chunks.push(character.to_string()),
		}
	}
	chunks.reverse();
	let mut lines: Vec<String> = Vec::new();
	while !chunks.is_empty() {
		if !lines.is_empty() && chunks.last().is_some_and(|chunk| chunk.starts_with(' ')) {
			chunks.pop();
		}
		let mut current: Vec<String> = Vec::new();
		let mut length = 0;
		while let Some(chunk) = chunks.last() {
			let size = chunk.chars().count();
			if length + size > WIDTH {
				break;
			}
			length += size;
			current.extend(chunks.pop());
		}
		if current.is_empty() {
			current.extend(chunks.pop());
		}
		if current.last().is_some_and(|chunk| chunk.starts_with(' ')) {
			current.pop();
		}
		if !current.is_empty() {
			lines.push(current.concat());
		}
	}
	lines
}

/// `text` as comment lines, each paragraph wrapped (clap joins a doc
/// comment's lines into one).
fn comment(text: &str) -> Vec<String> {
	let mut out = Vec::new();
	for line in text.lines() {
		if line.trim().is_empty() {
			out.push("#".to_owned());
		} else {
			out.extend(wrap(line).into_iter().map(|part| format!("# {part}")));
		}
	}
	out
}

fn capitalized(text: &str) -> String {
	let mut characters = text.chars();
	characters.next().map(|first| first.to_uppercase().chain(characters).collect()).unwrap_or_default()
}

pub(crate) fn describe(variable: &Variable) -> Vec<String> {
	let mut facts = Vec::new();
	if variable.required {
		facts.push("Required.".to_owned());
	}
	if let Some(condition) = &variable.required_when {
		facts.push(format!("Required while {} is {}.", condition.variable, condition.value));
	}
	if let Some(bounds) = &variable.bounds {
		let conditions = bounds.when.iter().enumerate().fold(String::new(), |mut out, (index, when)| {
			let joiner = if index == 0 { " while" } else { " and" };
			let value = if when.value == SET { "set" } else { &when.value };
			let _ = write!(out, "{joiner} {} is {value}", when.variable);
			out
		});
		facts.push(format!("{}{conditions}.", capitalized(&bound_text(bounds))));
	}
	match variable.kind {
		Kind::Enum => facts.push(format!("One of: {}.", variable.values.join(", "))),
		Kind::Bool => facts.push("true or false.".to_owned()),
		_ => {}
	}
	if let Some(delimiter) = variable.delimiter {
		facts.push(format!("A list, separated by '{delimiter}'."));
	}
	if variable.secret {
		facts.push("Secret: keep it out of the repository.".to_owned());
	}
	if variable.class == Class::Private {
		facts.push("Private: it names an account or a person, so it stays out of the repository (CFG11, #607, commits it encrypted).".to_owned());
	}
	facts
}

type Readers<'a> = BTreeMap<&'a str, Vec<(&'a str, &'a Variable)>>;

/// `example.env`. `deployed`: the binaries some `deploy/<role>/` holds a file
/// for; another's "ours" variables are left out too, where it is deployed.
pub(crate) fn render(schemas: &[Schema], compose: &ComposeVariables, head: &str, deployed: &BTreeSet<String>) -> String {
	let mut out: Vec<String> = vec![BANNER.to_owned(), String::new(), head.trim_end_matches('\n').to_owned()];
	let mut readers: Readers<'_> = BTreeMap::new();
	for schema in schemas {
		for variable in &schema.variables {
			readers.entry(variable.name.as_str()).or_default().push((schema.binary.as_str(), variable));
		}
	}
	let ours: BTreeSet<&str> = readers
		.iter()
		.filter(|(_, read)| read.iter().any(|(_, other)| other.class == Class::Ours))
		.map(|(name, _)| *name)
		.collect();
	let mut written: BTreeSet<&str> = BTreeSet::new();
	for schema in schemas {
		binary_section(&mut out, schema, &readers, &ours, &mut written, compose, deployed.contains(&schema.binary));
	}
	compose_section(&mut out, compose, &written);
	let mut text = out.join("\n");
	text.push('\n');
	text
}

/// One binary's section: every variable no earlier section listed and that
/// is not "ours", with its help and default.
fn binary_section<'a>(
	out: &mut Vec<String>,
	schema: &'a Schema,
	readers: &Readers<'a>,
	ours: &BTreeSet<&str>,
	written: &mut BTreeSet<&'a str>,
	compose: &ComposeVariables,
	deployed: bool,
) {
	out.extend(
		[
			"",
			"###############################################",
			&format!("#   {}", schema.binary),
			"###############################################",
		]
		.map(str::to_owned),
	);
	if !schema.about.is_empty() {
		out.push(format!("# {}.", schema.about));
	}
	let decided: Vec<&str> = schema.variables.iter().map(|variable| variable.name.as_str()).filter(|name| ours.contains(name)).collect();
	if !decided.is_empty() {
		let note = if deployed {
			format!(
				"Decided per host in deploy/<role>/{}.env, never here (CFG9, #604), and the preflight refuses one set in .env: {}.",
				schema.binary,
				decided.join(", ")
			)
		} else {
			format!(
				"Not set here, as \"ours\" (CFG9, #604): {}. No deploy/<role>/ holds {} yet, so they are set where it is deployed.",
				decided.join(", "),
				schema.binary
			)
		};
		out.extend(comment(&note));
	}
	let listed: Vec<&str> = schema
		.variables
		.iter()
		.map(|variable| variable.name.as_str())
		.filter(|name| written.contains(name) && !ours.contains(name))
		.collect();
	if !listed.is_empty() {
		out.extend(comment(&format!("Also reads {}, listed above.", listed.join(", "))));
	}
	let mut group: Option<&str> = None;
	for variable in &schema.variables {
		let name = variable.name.as_str();
		if written.contains(name) || ours.contains(name) {
			continue;
		}
		written.insert(name);
		if variable.group.as_deref() != group {
			group = variable.group.as_deref();
			if let Some(group) = group {
				out.extend([String::new(), format!("# ── {group} ──")]);
			}
		}
		out.push(String::new());
		out.extend(comment(&variable.help));
		let mut facts = describe(variable);
		let others: Vec<String> = readers[name]
			.iter()
			.filter(|(binary, _)| *binary != schema.binary)
			.map(|(binary, other)| {
				if other.default == variable.default {
					(*binary).to_owned()
				} else {
					format!("{binary} (default {})", other.default.as_deref().unwrap_or("None"))
				}
			})
			.collect();
		if !others.is_empty() {
			facts.push(format!("Also read by {}.", others.join(", ")));
		}
		if let Some(used) = compose.get(name) {
			let default = used.default.as_ref().map(|default| format!(" (default {default})")).unwrap_or_default();
			facts.push(format!("docker compose also reads it: {}{default}.", used.files.join(", ")));
		}
		if !facts.is_empty() {
			out.extend(comment(&facts.join(" ")));
		}
		out.push(format!("# {name}={}", quote(variable.default.as_deref().unwrap_or_default())));
	}
}

/// The variables only docker compose reads, by name.
fn compose_section(out: &mut Vec<String>, compose: &ComposeVariables, written: &BTreeSet<&str>) {
	let mut rest: Vec<_> = compose.values().filter(|variable| !written.contains(variable.name.as_str())).collect();
	if rest.is_empty() {
		return;
	}
	out.extend(
		[
			"",
			"###############################################",
			"#   docker compose",
			"###############################################",
			"# Read by docker compose itself, when it reads the compose files, not by",
			"# a binary. Shell variables win over these lines.",
		]
		.map(str::to_owned),
	);
	rest.sort_by(|a, b| a.name.cmp(&b.name));
	for variable in rest {
		out.push(String::new());
		let help = if variable.help.is_empty() { &variable.message } else { &variable.help };
		if !help.is_empty() {
			out.extend(comment(help));
		}
		let required = if variable.required { "Required: every service waits on it. " } else { "" };
		out.extend(comment(&format!("{required}Read in {}.", variable.files.join(", "))));
		out.push(format!("# {}={}", variable.name, quote(variable.default.as_deref().unwrap_or_default())));
	}
}

#[cfg(test)]
mod tests {
	use super::{render, wrap};
	use crate::{compose::variables, dotenv::parse, schema::fixture::ours};
	use std::collections::BTreeSet;

	#[test]
	fn a_line_wraps_as_textwrap_wraps_it() {
		let long = "word ".repeat(30);
		let wrapped = wrap(long.trim());
		assert!(wrapped.iter().all(|line| line.len() <= 76) && wrapped.len() == 2, "{wrapped:?}");
		assert_eq!(wrap(&"x".repeat(80)), ["x".repeat(80)], "a long word is never broken");
	}

	#[test]
	fn example_env_lists_what_stays_off_git_and_sets_nothing() {
		let compose = variables(&[(
			"a.yml".to_owned(),
			"      # ROOT: the root.\n      - ${ROOT:?set ROOT}/x\n      - ${PORT:-3000}\n".to_owned(),
		)]);
		let deployed = BTreeSet::from(["probe".to_owned()]);
		let example = render(&[ours()], &compose, "# head", &deployed);
		let flat: String = example.lines().map(|line| line.trim_start_matches('#').trim()).collect::<Vec<_>>().join(" ");
		assert!(
			!example.contains("ON=") && example.contains("# PORT=\"3000\"") && example.contains("# KEY=\"\"") && example.contains("# ACCOUNT=\"\""),
			"{example}"
		);
		assert!(
			flat.contains("ON, URL, WHO, DAYS, WIRE.") && flat.contains("docker compose also reads it: a.yml (default 3000).") && flat.contains("Private:"),
			"{flat}"
		);
		assert!(example.contains("# ROOT=\"\"") && flat.contains("ROOT: the root."));
		assert!(parse(&example).is_empty(), "every line is commented out");
		let undeployed = render(&[ours()], &compose, "# head", &BTreeSet::new());
		assert!(undeployed
			.lines()
			.map(|line| line.trim_start_matches('#').trim())
			.collect::<Vec<_>>()
			.join(" ")
			.contains("No deploy/<role>/ holds probe yet"));
	}
}
